```apex
public class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            return executeSearch(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException('Search failed: ' + e.getMessage());
        }
    }

    private static List<SObject> executeSearch(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // Validate fields list
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // Validate object name
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }

        // Resolve object (case-insensitive)
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType objType = null;
        String resolvedObjectName = null;
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                objType = globalDescribe.get(key);
                resolvedObjectName = key;
                break;
            }
        }
        if (objType == null) {
            throw new SearchException('Object \'' + objectApiName + '\' does not exist.');
        }

        // Get field map
        Map<String, Schema.SObjectField> fieldMap = objType.getDescribe().fieldsMap();

        // Build SELECT clause (Id always included, then requested fields, deduplicated case-insensitively)
        List<String> selectFields = new List<String>();
        Set<String> seenFields = new Set<String>();
        selectFields.add('Id');
        seenFields.add('id');

        for (String field : fields) {
            if (String.isBlank(field)) {
                throw new SearchException('Field name in fields list cannot be blank.');
            }
            String resolved = resolveFieldName(fieldMap, field);
            if (resolved == null) {
                throw new SearchException('Field \'' + field + '\' is not a field of \'' + resolvedObjectName + '.');
            }
            if (!seenFields.contains(resolved.toLowerCase())) {
                selectFields.add(resolved);
                seenFields.add(resolved.toLowerCase());
            }
        }

        // Build WHERE clause
        String whereClause = '';
        if (filters != null && !filters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String filterField : filters.keySet()) {
                if (filterField == null || String.isBlank(filterField)) {
                    throw new SearchException('Filter field name cannot be null or blank.');
                }
                String resolvedFilterField = resolveFieldName(fieldMap, filterField);
                if (resolvedFilterField == null) {
                    throw new SearchException('Filter field \'' + filterField + '\' is not a field of \'' + resolvedObjectName + '.');
                }
                Object value = filters.get(filterField);
                conditions.add(resolvedFilterField + ' = ' + formatValue(value));
            }
            whereClause = ' WHERE ' + String.join(conditions, ' AND ');
        }

        // Build ORDER BY clause
        String orderByClause = '';
        if (orderByField != null && !String.isBlank(orderByField)) {
            String resolvedOrderField = resolveFieldName(fieldMap, orderByField);
            if (resolvedOrderField == null) {
                throw new SearchException('Order-by field \'' + orderByField + '\' is not a field of \'' + resolvedObjectName + '.');
            }
            orderByClause = ' ORDER BY ' + resolvedOrderField + ' ASC';
        }

        // Assemble query
        String query = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + resolvedObjectName
            + whereClause
            + orderByClause
            + ' LIMIT ' + String.valueOf(maxRows);

        // Execute - respects sharing and FLS by default
        return Database.query(query);
    }

    private static String resolveFieldName(Map<String, Schema.SObjectField> fieldMap, String fieldName) {
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldName)) {
                return key;
            }
        }
        return null;
    }

    private static String formatValue(Object value) {
        if (value == null) {
            return 'NULL';
        }
        if (value instanceof Boolean) {
            return String.valueOf(value);
        }
        if (value instanceof Date) {
            return "'" + ((Date)value).format('yyyy-MM-dd') + "'";
        }
        if (value instanceof DateTime) {
            return "'" + ((DateTime)value).formatGmt("yyyy-MM-dd'T'HH:mm:ss") + "'";
        }
        if (value instanceof Integer) {
            return String.valueOf(value);
        }
        if (value instanceof Long) {
            return String.valueOf(value);
        }
        if (value instanceof Decimal) {
            return String.valueOf(value);
        }
        // String, Id (extends String), and any other type
        return "'" + String.escapeSingleQuotes(String.valueOf(value)) + "'";
    }
}
