        }
        if (obj instanceof Decimal) {
            Decimal d = (Decimal) obj;
            if (d.fractPart() != 0) {
                throw new PayloadException(fieldName + ' is not an integer');
            }
            return d.intValue();
        }
        throw new PayloadException(fieldName + ' is not a number');
    }

    private static Decimal toDecimal(Object obj, String fieldName) {
        if (obj instanceof Decimal) {
            return (Decimal) obj;
        }
        if (obj instanceof Integer) {
            return (Decimal) (Integer) obj;
        }
        throw new PayloadException(fieldName + ' is not a number');
    }
