public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        // --- Input validation ------------------------------------------------
        if (objectApiName == null || objectApiName.isBlank()
         || fieldApiName == null || fieldApiName.isBlank()) {
            throw new PicklistServiceException(
                'Object and field API names must not be null or blank.');
        }

        // --- Resolve object (case-insensitive) --------------------------------
        Map<String, Schema.SObjectDescribe> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectDescribe sObjectDescribe = null;
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                sObjectDescribe = globalDescribe.get(key);
                break;
            }
        }
        if (sObjectDescribe == null) {
            throw new PicklistServiceException(
                'Object does not exist: ' + objectApiName);
        }

        // --- Resolve field (case-insensitive) ---------------------------------
        Map<String, Schema.SObjectFieldDescribe> fieldsMap = sObjectDescribe.fields.getMap();
        Schema.SObjectFieldDescribe fieldDescribe = null;
