public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {}

    public void execute(SchedulableContext sc) {
        DateTime now = Datetime.now();
        DateTime thirtyDaysAgo = now.addDays(-30);
        DateTime oneHundredEightyDaysAgo = now.addDays(-180);

        List<Id> idsToDelete = new List<Id>();

        // Non-ERROR logs (including null/blank) older than 30 days
        for (FB_Integration_Log__c log : [
            SELECT Id FROM FB_Integration_Log__c 
            WHERE (Level__c != 'ERROR' OR Level__c = NULL) AND CreatedDate < :thirtyDaysAgo
            LIMIT 5000
        ]) {
            idsToDelete.add(log.Id);
        }

        // ERROR logs older than 180 days
        for (FB_Integration_Log__c log : [
            SELECT Id FROM FB_Integration_Log__c 
            WHERE Level__c = 'ERROR' AND CreatedDate < :oneHundredEightyDaysAgo
            LIMIT 5000
        ]) {
            idsToDelete.add(log.Id);
        }

        // Delete in batches of 500
        Integer batchSize = 500;
        for (Integer i = 0; i < idsToDelete.size(); i += batchSize) {
            Integer end = Math.min(i + batchSize, idsToDelete.size());
            Delete idsToDelete.sublist(i, end);
        }
    }

    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 ? * *';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
