            + 'SELECT ' + String.join(accountFieldNames, ', ')
            + ', (SELECT ' + String.join(contactFieldNames, ', ')
            + ' FROM Contacts) FROM Account WHERE Id IN :accountIds';

        return (List<Account>) Database.query(soql);
    }

